        price_quote(rate) * 2
    }
}

pub mod api {
    /// The API entry point — this layer is allowed to perform I/O.
    pub fn get_quote() -> u64 {
        let rate = crate::infra::fetch_rate();
        crate::domain::quote_bulk(rate)
    }
}

